// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MONEY_BOX c;
    Recorder rec;

    function setUp() public {
        c = new MONEY_BOX();
        rec = new Recorder();
    }

    function testFuzz_property(uint128 amount, uint64 lockTime, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        // initialize SetLogFile to a live recorder BEFORE initialization
        c.SetLogFile(address(rec));
        vm.deal(actor, amount);
        vm.prank(actor);
        try c.Put{value: amount}(lockTime) {
            // Put succeeded: the log must have received exactly this deposit
            assertTrue(rec.count() == 1 && rec.total() == uint256(amount) && rec.lastSender() == actor);
        } catch {
            // if Put reverted, the log was never contacted — reference never does this
            assertTrue(false);
        }
    }
}

contract Recorder {
    uint public count;
    uint public total;
    address public lastSender;

    function AddMessage(address adr, uint256 val, string memory data) external {
        data;
        count++;
        total += val;
        lastSender = adr;
    }

    receive() external payable {}
}
